func (r *queryResolver) CheckReplyPermission(ctx context.Context, postID string) (bool, error) {
	claims := middleware.GetUserClaims(ctx)
	if claims == nil {
		return false, errors.New("unauthorized")
	}

	res, err := r.ContentServiceClient.CheckReplyPermission(ctx, &content_proto.CheckReplyPermissionRequest{
		PostId: postID,
		UserId: claims.UserID,
	})
	if err != nil {
		return false, fmt.Errorf("failed to check reply permission: %w", err)
	}
	if res.Error != nil {
		return false, errors.New(res.Error.Message)
	}

	return res.CanReply, nil
}

