// HomeFeed is the resolver for the homeFeed field.
func (r *queryResolver) HomeFeed(ctx context.Context, first int, after *string) (*model.PostConnection, error) {
	fmt.Printf("[Gateway] HomeFeed query received with first: %d\n", first)

	claims := middleware.GetUserClaims(ctx)
	if claims == nil {
		fmt.Printf("[Gateway] HomeFeed unauthorized: no user claims\n")
		return nil, fmt.Errorf("unauthorized")
	}

	fmt.Printf("[Gateway] HomeFeed calling content-service GetTimeline for user: %s\n", claims.UserID)

	// 调用内容服务获取时间线
	res, err := r.ContentServiceClient.GetTimeline(ctx, &content_proto.GetTimelineRequest{
		UserId: claims.UserID,
		Limit:  int32(first),
		Cursor: "", // 简化处理
	})
	if err != nil {
		fmt.Printf("[Gateway] HomeFeed content-service call failed: %v\n", err)
		return nil, fmt.Errorf("failed to get timeline: %w", err)
	}
	if res.Error != nil {
		fmt.Printf("[Gateway] HomeFeed content-service returned error: %s\n", res.Error.Message)
		return nil, errors.New(res.Error.Message)
	}

	fmt.Printf("[Gateway] HomeFeed got %d posts from content-service\n", len(res.Posts))

	// 转换为GraphQL连接类型
	edges := make([]model.PostEdge, len(res.Posts))
	for i, post := range res.Posts {
		edges[i] = model.PostEdge{
			Node:   r.postProtoToGql(post),
			Cursor: post.Id,
		}
	}

	return &model.PostConnection{
		Edges: edges,
		PageInfo: &model.PageInfo{
			HasNextPage: res.HasMore,
			EndCursor:   nil,
		},
	}, nil
}

